jQuery(document).ready(function(){dataTables();jQuery(this).mousemove(function(e){idleTime=0});jQuery(this).keypress(function(e){idleTime=0});$('#DataTables_Table_0_wrapper tbody').find('tr').sort(function(a,b){return $('td:first',a).text().localeCompare($('td:first',b).text())}).appendTo('#DataTables_Table_0_wrapper table');jQuery('a[href="?lang=en"]').click(function(e){e.preventDefault();makeOverlay();window.location.href=jQuery(this).attr('href')});jQuery('a[href="?lang=he"]').click(function(e){e.preventDefault();makeOverlay();window.location.href=jQuery(this).attr('href')})});function toggleScreen(buttonEl){let hashSrc=buttonEl.getAttribute("data-src");let src=hashSrc.replace("#","",hashSrc);let screenEl=document.getElementById(src);let screens=document.querySelectorAll(".screen");let buttons=document.querySelectorAll(".btn-nav-item");let pageTitle=document.querySelector(".page-title");let btnTitle=buttonEl.getAttribute("data-title");buttons.forEach((el)=>el.classList.remove("active"));buttonEl.classList.add("active");pageTitle.innerHTML=btnTitle;screens.forEach((el)=>el.classList.remove("active"));screenEl.classList.add("active")}
function toggleQrCode(){document.querySelector(".side-nav .qr-code").classList.toggle("show")}
function dataTables(){var table=jQuery(".data-table").DataTable()}
var timeoutID;function setup(){this.addEventListener("mousemove",resetTimer,!1);this.addEventListener("mousedown",resetTimer,!1);this.addEventListener("keypress",resetTimer,!1);this.addEventListener("DOMMouseScroll",resetTimer,!1);this.addEventListener("mousewheel",resetTimer,!1);this.addEventListener("touchmove",resetTimer,!1);this.addEventListener("MSPointerMove",resetTimer,!1);startTimer()}
setup();function startTimer(){timeoutID=window.setTimeout(goInactive,30000)}
function resetTimer(e){window.clearTimeout(timeoutID);goActive()}
function goInactive(){if(jQuery("html").attr("lang")!="en"){jQuery('a[data-src="#faculty-members"], button.is-close').click();jQuery(".qr-code").removeClass("show")}else{makeOverlay();window.location="?lang=he"}
document.querySelector(".page-title").innerHTML=staffObj.pageTitle}
function goActive(){startTimer()}
function scrollToTableTop(){jQuery('.table-wrap').scrollTop(0)}
function makeOverlay(){var overlay=document.createElement('div');overlay.id='overlay';overlay.style.position='fixed';overlay.style.top=0;overlay.style.left=0;overlay.style.width='100%';overlay.style.height='100%';overlay.style.backgroundColor='rgba(0,0,0,0.5)';overlay.style.zIndex=999;document.body.appendChild(overlay);var spinner=document.createElement('div');spinner.id='spinner';spinner.style.position='fixed';spinner.style.top='50%';spinner.style.left='50%';spinner.style.width='50px';spinner.style.height='50px';spinner.style.marginTop='-25px';spinner.style.marginLeft='-25px';spinner.style.border='8px solid #f3f3f3';spinner.style.borderTop='8px solid #3498db';spinner.style.borderRadius='50%';spinner.style.animation='spin 2s linear infinite';spinner.style.zIndex=1000;document.body.appendChild(spinner);var style=document.createElement('style');style.innerHTML='@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }';document.head.appendChild(style)}